package cn.workbench;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.beans.factory.annotation.Value;import java.time.*;import java.util.*;
@Component public class Jobs {
 final Store db;final Records r;final KpiController kpi;final TransactionTemplate tx;final boolean enabled;public Jobs(Store d,Records r,KpiController k,PlatformTransactionManager manager,@Value("${task.jobs-enabled:true}")boolean enabled){db=d;this.r=r;kpi=k;tx=new TransactionTemplate(manager);this.enabled=enabled;}
 @Scheduled(fixedDelayString="${TASK_OUTBOX_DELAY_MS:5000}") public void outbox(){if(!enabled)return;try{new WecomDelivery(db,r,tx).run();}catch(Exception e){java.util.logging.Logger.getLogger(Jobs.class.getName()).severe("OUTBOX_WORKER_FAILED");}}

 @Scheduled(fixedDelayString="${TASK_JOB_DELAY_MS:60000}") public void reminders(){if(!enabled)return;Instant now=Instant.now();for(var sub:r.list("SUB_TASK",null,null)){if(Set.of("ACCEPTED","CANCELLED").contains(sub.get("status")))continue;var task=r.get(Jsons.number(sub.get("taskId")));if(Set.of("DRAFT","COMPLETED","CANCELLED").contains(task.get("status")))continue;Instant deadline=Records.instant(sub.get("deadline"));String type=null;if(deadline.isBefore(now))type="OVERDUE-"+LocalDate.now(ZoneId.of("Asia/Shanghai"));else if(deadline.isBefore(now.plus(Duration.ofHours(24))))type="DUE24-"+deadline.toEpochMilli();else if(sub.get("status").equals("PENDING_RECEIVE")){Instant dispatched=sub.get("dispatchedAt")==null?Records.instant(sub.get("createdAt")):Records.instant(sub.get("dispatchedAt"));if(dispatched.plus(Duration.ofHours(48)).isBefore(now))type="UNRECEIVED48";else if(dispatched.plus(Duration.ofHours(24)).isBefore(now))type="UNRECEIVED24";}if(type!=null){String event=type;once("REMINDER-"+sub.get("id")+"-"+type,()->{var current=r.lock(Jsons.number(task.get("id")));if(deadline.isBefore(now)&&!Boolean.TRUE.equals(current.get("everOverdue"))){current.put("everOverdue",true);r.save(current);}if(deadline.isBefore(now)){var lateSub=r.lock(Jsons.number(sub.get("id")));TaskService.preserveSubOverdue(lateSub);r.save(lateSub);}Set<Long> users=new HashSet<>(db.assignees(Jsons.number(sub.get("id"))));for(var u:db.users())if(db.scopes(Jsons.number(u.get("id"))).stream().anyMatch(s->"DEPT_HEAD".equals(s.get("role"))&&Objects.equals(s.get("deptId")==null?null:Jsons.integer(s.get("deptId")),Jsons.integer(sub.get("deptId")))))users.add(Jsons.number(u.get("id")));for(long uid:users)db.outbox(Records.map("key","JOB-"+sub.get("id")+"-"+event+"-"+uid,"company",sub.get("companyId"),"recipient",uid,"task",task.get("id"),"title","任务提醒："+event));});}}lockKpi();monthly();}
 void lockKpi(){for(var run:r.list("KPI_RUN",null,null))if(!Boolean.TRUE.equals(run.get("simulation"))&&run.get("lockedAt")==null&&!Records.instant(run.get("publishedAt")).plus(Duration.ofDays(7)).isAfter(Instant.now()))once("KPI-LOCK-"+run.get("id"),()->{var current=r.lock(Jsons.number(run.get("id")));current.put("lockedAt",Instant.now().toString());current.put("status","LOCKED");r.save(current);});}
 @Scheduled(cron="0 0 2 1 * *",zone="Asia/Shanghai") public void monthly(){if(!enabled)return;YearMonth period=YearMonth.now(ZoneId.of("Asia/Shanghai")).minusMonths(1);for(var company:r.list("COMPANY",null,null))for(var template:r.list("KPI_TEMPLATE",null,null))if(Boolean.TRUE.equals(template.get("approved")))once("KPI-MONTH-"+company.get("id")+"-"+period+"-"+template.get("id"),()->kpi.run(new Policy.Actor(0,"ADMIN",Jsons.integer(company.get("id")),null,0),Records.map("companyId",company.get("id"),"period",period.toString(),"templateId",template.get("id"),"simulation",false)));}
 void once(String key,Runnable work){try{tx.execute(status->{db.startJob(key);work.run();db.finishJob(key);return null;});}catch(org.springframework.dao.DuplicateKeyException alreadyDone){}catch(Exception e){java.util.logging.Logger.getLogger(Jobs.class.getName()).severe("JOB_FAILED key="+key+" type="+e.getClass().getSimpleName());}}
}
